(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zr-sj-prepa-gyneco-j4-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zr-sj-prepa-gyneco-j4-sf3\",\n \"titre\": \"Préparation D.E (J) · J4 Gynéco-obstétrique SF3\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 56,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n   \"sha256\": \"9ee0174cae6a310ff499e14b7685289c3bf3a2155e497e3971a6b1d18f45aa2e\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J4 (SF3)\",\n     \"slug\": \"prepa-gyneco-j4-sf3\",\n     \"pages\": \"\",\n     \"count\": 56,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La nidation a lieu dans la trompe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La fécondation a lieu dans le 1/3 externe de la trompe ; l'œuf migre 4 à 5 jours puis se niche normalement dans la cavité utérine vers le 7e jour (stade blastocyste). Une nidation dans la trompe est une grossesse extra-utérine.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Grossesse extra-utérine (rappels)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lors de la traction contrôlée du cordon, si le cordon se coupe, la révision utérine s'impose.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Si le cordon est arraché alors que le placenta n'est pas sorti, il faut faire une délivrance artificielle (extraction manuelle du placenta) suivie d'une injection d'ocytocine. La révision utérine, elle, contrôle un utérus déjà vide.\\n\\nSource : Module SONU – PNSME, GATPA – traction contrôlée du cordon p. 52-53\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la délivrance il est impératif de réaliser une révision utérine pour s'assurer que l'utérus est vide\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après une délivrance normale, on examine le placenta. La révision utérine n'est indiquée que si le placenta ou les membranes sont incomplets, ou devant une hémorragie ; elle n'est pas systématique.\\n\\nSource : Module SONU – PNSME, GATPA p. 53 ; Cours de soins obstétricaux L2 SF, Hémorragies de la délivrance p. 106\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La CPN recentrée ne concerne que les grossesses à risque.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La CPN recentrée est l'approche des soins prénatals proposée à toutes les gestantes : actions ciblées, évaluation focalisée à chaque visite, dépistage et prise en charge des complications, plan de préparation à l'accouchement.\\n\\nSource : Cours de soins obstétricaux L2 SF, CPN recentrée (définition, 5 principes) ; SONU L2 SF (2025-2026), CPN recentrée\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La MILDA est instituée pour la prévention de l'anémie chez la femme enceinte.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La MILDA (moustiquaire imprégnée d'insecticide à longue durée d'action) sert à prévenir le paludisme. La prévention de l'anémie repose sur l'acide folique et le fer.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), CPN – soins préventifs ; Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 6\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant un avortement molaire, la sage-femme doit prendre une voie veineuse et réaliser l'AMIU après l'accord de son médecin responsable.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant une môle hydatiforme, la sage-femme met la patiente en condition (voie veineuse) et organise la référence. L'évacuation de la môle et le suivi (dosages hCG) relèvent du médecin en milieu spécialisé ; ce n'est pas un geste que la sage-femme réalise sur simple accord.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Métrorragies du 1er trimestre – môle hydatiforme p. 132-133 (en partie hors cours pour l'AMIU)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La procidence du cordon est une chute du cordon en avant de la présentation à membranes intactes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La procidence est la chute du cordon en avant de la présentation après rupture des membranes (c'est le risque immédiat d'une rupture des membranes). À membranes intactes, on parle de procubitus.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Rupture artificielle des membranes (risque de procidence) ; définition du procubitus (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La souffrance fœtale chronique survient au cours du travail d'accouchement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La souffrance fœtale chronique s'installe pendant la grossesse (insuffisance placentaire, grossesse prolongée…) et se traduit par un RCIU. Pendant le travail, il s'agit d'une souffrance fœtale aiguë.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Grossesse prolongée p. 123 ; Anomalies de la hauteur utérine p. 53\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le placenta prævia fait partie des causes de métrorragies du 1er trimestre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Au 1er trimestre, les métrorragies viennent de l'avortement, de la môle, de la GEU ou des lésions du col. Le placenta prævia, comme l'HRP et la rupture utérine, est une cause des 2e et 3e trimestres.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Métrorragies pendant la grossesse p. 11\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant un avortement molaire, la sage-femme doit prendre une voie veineuse et réaliser l'AMIU après l'accord de son médecin responsable.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Même énoncé que la question 6 : la sage-femme met en condition et réfère ; l'évacuation de la môle se fait en milieu spécialisé sous la responsabilité du médecin. Remarque : Cette question est en double dans le sujet (identique à la question 6).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Môle hydatiforme p. 132-133\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétention placentaire est la première cause d'Hémorragie du post partum immédiat\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Parmi les « 4T » (Tonus, Traumatisme, Tissu, Thrombus), la première cause d'HPPI est l'atonie utérine (+++), avant les déchirures et la rétention placentaire.\\n\\nSource : Module SONU – PNSME, Hémorragie du post-partum p. 50\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le premier signe de puberté chez le garçon est l'augmentation du volume testiculaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez le garçon, la puberté commence par l'augmentation du volume des testicules (vers 11-12 ans), suivie de la pilosité pubienne puis de la croissance de la verge.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La patiente VIH + sous traitement peut recevoir le TPI dans le même temps\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La gestante VIH+ sous cotrimoxazole ne doit pas recevoir la SP (TPI) : le cotrimoxazole protège déjà contre le paludisme et l'association entraîne un surdosage en sulfamides. Si elle ne prend pas de cotrimoxazole, le TPI est le même que chez la femme séronégative. Remarque : Le cours parle de la patiente « sous cotrimoxazole » ; « sous traitement » est compris ici dans ce sens.\\n\\nSource : SONU L2 SF (2025-2026), Prévention du paludisme pendant la grossesse\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La grossesse gémellaire est un facteur de risque de grossesse prolongée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La grossesse gémellaire expose au contraire à l'accouchement prématuré : les grossesses multiples font partie des causes ovulaires de MAP (environ 10 %).\\n\\nSource : Cours MAP (menace d'accouchement prématuré), Étiologies – causes ovulaires\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La dessiccation est une complication survenant dans la procidence du cordon 1er degré.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le refroidissement et la dessiccation de la gelée de Wharton (entraînant un spasme des vaisseaux ombilicaux) surviennent lorsque le cordon est exposé à l'air libre hors des voies génitales, c'est-à-dire dans la procidence du cordon du 3e degré (extériorisée à la vulve), et non au 2e degré (intravaginal).\\n\\nSource : Cours de Gynéco-Obstétrique — Physiopathologie et degrés de la procidence du cordon.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ovulation est presque toujours précédée d'un pic de FSH\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"C'est le pic de LH (hormone lutéinisante) qui déclenche l'ovulation, environ 36 heures avant. Un petit pic de FSH l'accompagne, mais le signal de l'ovulation est le pic de LH.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Ménopause (rôle du pic de LH) p. 161 (en partie hors cours)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une mère de Rh- ayant accouché d'un bébé de Rh+ doit recevoir une injection d'immunoglobuline anti-D.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Pour prévenir l'allo-immunisation rhésus, la mère Rh– qui accouche d'un enfant Rh+ reçoit des immunoglobulines anti-D (Rhophylac®…) le plus tôt possible, dans les 72 heures ; la dose dépend du passage de sang fœtal.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Allo-immunisation rhésus – prévention p. 20\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le port du préservatif est un moyen de prévention de la rubéole\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La rubéole est un virus à transmission respiratoire (gouttelettes) ; le préservatif ne la prévient pas. La prévention repose sur la vaccination avant la grossesse ; le vaccin, vivant, ne doit pas être fait pendant la grossesse.\\n\\nSource : Cours Médicaments et grossesse, Les vaccins ; mode de transmission (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le régime sans sel n'est pas recommandé pour les patientes présentant une hypertension artérielle au cours de la grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En cas de toxémie gravidique, la gestante doit manger le sel normalement : pas de régime sans sel. Il n'est indiqué que si une HTA antérieure à la grossesse était déjà traitée par régime sans sel.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), HTA et grossesse – régime ; CPN (régime normo-salé)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant une MAP sur une grossesse à 35 SA il faut réaliser une corticothérapie maturative anténatale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après 35 SA, on s'abstient de traitement et on laisse accoucher. La corticothérapie anténatale (bétaméthasone 12 mg IM, à répéter 24 h plus tard) est faite avant 34 SA.\\n\\nSource : Cours MAP (menace d'accouchement prématuré), Traitement – indications selon l'âge gestationnel\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le diabète gestationnel, le dépistage par (HGPO) se fait à la 22ème semaine de la grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le dépistage ne se fait pas à 22 SA. Chez la femme à risque, il se fait vers la 24e SA (test de O'Sullivan puis HGPO si positif) ; chez la femme sans facteur de risque de plus de 25 ans, à la 30e SA. Classiquement, la période de dépistage est 24-28 SA. Remarque : Le terme du dépistage chez la femme à risque est peu lisible dans la copie du cours (p. 45) ; la période 24-28 SA est le repère classique.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Diabète gestationnel – dépistage p. 45\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont les deux types de placentas praevia observés au cours du travail d'accouchement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le placenta recouvrant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le placenta latéral\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le placenta marginal\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le placenta non recouvrant\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le placenta central\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le placenta recouvrant ; D. Le placenta non recouvrant\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Pendant le travail, on distingue le placenta prævia recouvrant (le placenta occupe l'aire de dilatation, la poche des eaux n'est pas perçue) et non recouvrant (on perçoit la poche des eaux). Latéral, marginal et central sont la classification pendant la grossesse.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Placenta prævia – classification clinique\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans quel cas l'hypertension artérielle est-elle un facteur favorisant :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le placenta praevia\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'hématome retro placentaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La rupture utérine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La grossesse molaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. L'hématome retro placentaire\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'HRP est une complication classique de l'HTA gravidique et de la pré-éclampsie (douleur en coup de poignard, utérus dur, sang noir). Le placenta prævia et la rupture utérine sont liés à des causes mécaniques (cicatrices, multiparité…).\\n\\nSource : Cours HTA et pré-éclampsie, Complications IV-1-2 (HRP)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant la grossesse extra-utérine : cocher la réponse inexacte\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une grossesse qui peut évoluer à terme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une prolifération anormale du trophoblaste\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De localisation tubaire dans la majorité des cas\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Souvent asymptomatique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une prolifération anormale du trophoblaste\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La GEU est la nidation et le développement de l'œuf hors de la cavité utérine, le plus souvent dans la trompe. La « prolifération anormale du trophoblaste » définit la môle hydatiforme, pas la GEU. Remarque : Il n'y a pas d'option D dans le sujet. « Peut évoluer à terme » ne vaut que pour les rares GEU abdominales, citées par le cours parmi les localisations rares.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Grossesse extra-utérine (définition, localisations)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'utérus non gravide comprend 3 parties sauf un : Laquelle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le corps de l'utérus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le segment inferieur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'isthme utérin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le col utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Le segment inferieur\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Hors grossesse, l'utérus comprend le corps, l'isthme et le col. Le segment inférieur n'existe que pendant la grossesse : il se forme aux dépens de l'isthme, surtout au 3e trimestre.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Métrorragies (col, isthme ou segment inférieur, corps) ; formation du segment inférieur (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les organes génitaux internes comprennent les différents éléments suivant sauf un : lequel\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'utérus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le vagin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le clitoris\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les ovaires\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le clitoris\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les organes génitaux internes sont les ovaires, les trompes, l'utérus et le vagin. Le clitoris fait partie de la vulve, donc des organes génitaux externes.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les réponses suivantes précisez les deux (2) causes obstétricales indirectes de décès maternels :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémorragie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Avortement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Eclampsie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"VIH / SIDA\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Paludisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. VIH / SIDA ; E. Paludisme\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les causes indirectes viennent d'une maladie préexistante ou apparue pendant la grossesse et aggravée par elle : paludisme, anémie, hépatite, VIH/SIDA. Hémorragie, avortement et éclampsie sont des causes obstétricales directes.\\n\\nSource : Module SONU – PNSME, Causes de mortalité maternelle p. 13 ; Cours de soins obstétricaux L2 SF p. 5\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle de ces fonctions ne fait pas partis des SONU B :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Administration par voie parentérale d'antibiotiques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aspiration manuelle intra utérine de restes d'avortement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La transfusion sanguine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Administration utérotonique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La transfusion sanguine\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les SONU de base ont 7 fonctions (antibiotiques, ocytociques, anticonvulsivants parentéraux, délivrance artificielle, évacuation des restes d'avortement dont l'AMIU, accouchement assisté, réanimation néonatale). La transfusion et la césarienne s'ajoutent dans les SONU complets.\\n\\nSource : Cours de soins obstétricaux L2 SF, Fonctions des SONUB et SONUC p. 7 ; Module SONU – PNSME p. 15-16\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les affections suivantes, laquelle n'est pas responsables de RPM ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Placenta prævia\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Infection vaginale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Grossesse Gémellaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"VIH\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. VIH\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Les infections cervico-vaginales, les grossesses multiples et le placenta prævia font partie des causes de rupture prématurée des membranes et d'accouchement prématuré. Le VIH n'en est pas une cause reconnue. Remarque : Le cours MAP liste ces causes pour la menace d'accouchement prématuré, dont la RPM fait partie.\\n\\nSource : Cours MAP (menace d'accouchement prématuré), Étiologies (causes maternelles infectieuses et causes ovulaires)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont les dangers encourus par le fœtus en cas d'hypertension pendant la grossesse ? Citez les 2 bonnes réponses\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une naissance prématurée.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une malformation.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une mort fœtale.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un avortement du 1er trimestre.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Aucune de ces réponses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Une naissance prématurée. ; C. Une mort fœtale.\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les complications fœtales de l'HTA sont le RCIU, la souffrance fœtale aiguë, la mort in utero et la prématurité induite. L'HTA ne cause ni malformation ni avortement du 1er trimestre (elle apparaît après 20 SA).\\n\\nSource : Cours HTA et pré-éclampsie, Complications fœtales IV.2\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les vaccins ci-dessous, lequel est sans danger pendant la grossesse ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le vaccin contre l'hépatite A\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le vaccin antirubéoleux.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le vaccin antipoliomyélitique Sabin per os.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le vaccin de la Grippe\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Le vaccin de la Grippe\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le vaccin contre la grippe peut être fait pendant la grossesse (comme le tétanos, l'hépatite B, la polio inactivée, la rage, le méningocoque). Hépatite A et rubéole figurent parmi les vaccins à ne pas faire ; le Sabin oral est un vaccin vivant (seule la polio inactivée est autorisée).\\n\\nSource : Cours Médicaments et grossesse, Les vaccins ; Gynéco L2 IDE (INFAS 2025), CPN – soins préventifs\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelles sont les deux (2) mesures préventives que l'on peut proposer pour prévenir la récidive de la pré-éclampsie chez une femme à haut risque ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le régime sans sel.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La prise de 100 mg d'aspirine par jour jusqu'à 36 semaines.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La prise d'un antihypertenseur depuis le début de la grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La prise de la tension artérielle à chaque CPN\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'administration d'acide folique au cours de la grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La prise de 100 mg d'aspirine par jour jusqu'à 36 semaines. ; D. La prise de la tension artérielle à chaque CPN\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"L'aspirine à faible dose (60-100 mg/j), débutée avant 16 SA et arrêtée vers 36 SA, est indiquée en cas d'antécédent de pré-éclampsie. La prise de la TA à chaque CPN permet de dépister tôt une récidive. Le régime sans sel est déconseillé. Remarque : La prise de TA est une mesure de surveillance et de dépistage plus que de prévention au sens strict.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), HTA et grossesse – aspirine (V-1.2)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle de ces méthodes de planification familiale est contre-indiquée dans le post partum immédiat ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"DIU à la progestérone\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ligatures tubaires\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Implants\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Contraceptifs injectables\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Contraceptifs injectables\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dans le tableau des critères d'éligibilité du post-partum (allaitement, moins de 48 h), les injectables progestatifs (DMPA-NET) sont en catégorie 3, alors que l'implant (2), le DIU au lévonorgestrel (2) et le DIU au cuivre (1) restent utilisables. La ligature tubaire peut aussi se faire après l'accouchement.\\n\\nSource : Cours de SR/PF L2 (INFAS 2023), Critères d'éligibilité dans le post-partum (3.5) ; Document SSR L2 SF (cours SR/PF, INFAS)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel de ces éléments ne fait pas partie des principaux signes cliniques du cancer du col ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une ulcération cervicale saignant au contact.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des ménorragies.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des métrorragies provoquées.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des leucorrhées plus ou moins striées de sang.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Des ménorragies.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cancer du col donne des métrorragies de contact (rapports, toilette), des leucorrhées parfois sanglantes et, au spéculum, un bourgeon ou une ulcération qui saigne au contact. Les ménorragies (règles trop abondantes) évoquent plutôt un fibrome.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Cancer du col – signes cliniques ; Fibrome utérin\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel de ces éléments ne fait pas partie de la prise en charge des complications thromboembolique dans le post partum ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bas de contention\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Héparinothérapie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Antibiothérapie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Levé précoce\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Antibiothérapie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La prévention et le traitement de la phlébite reposent sur le lever précoce, la mobilisation, les bas de contention et l'héparine (HBPM). L'antibiothérapie traite l'infection, pas la thrombose.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Complications des suites de couches – phlébite p. 107 ; Cardiopathie et grossesse p. 42\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les cancers ci-dessous, lequel est le premier cancer de femme dans le monde?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cancer de l'endomètre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cancer du col de l'utérus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cancer du sein\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cancer de l'ovaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Cancer du sein\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cancer du sein est le premier cancer de la femme ; en Côte d'Ivoire, il est suivi du cancer du col de l'utérus. Remarque : Le cours donne ce classement pour la Côte d'Ivoire ; il est le même au niveau mondial (hors cours).\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Le cancer du sein (pertinence)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les complications suivantes, lequel n'est pas une complication infectieuse des suites de couche?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Endométrite du post partum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rétention placentaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pelvi péritonite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Infection urinaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Rétention placentaire\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Endométrite, pelvipéritonite et infection urinaire sont des infections du post-partum. La rétention placentaire est une cause d'hémorragie (le « T » de Tissu), même si elle peut secondairement favoriser une endométrite.\\n\\nSource : Module SONU – PNSME, HPP – les 4T p. 50 ; Cours de soins obstétricaux L2 SF, HPP tardif p. 108\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel de ces éléments ne fait pas partie des risques néonataux du diabète ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypocalcémie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Anémie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hypoglycémie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Détresse respiratoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Anémie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le nouveau-né de mère diabétique est exposé à l'hypoglycémie, l'hypocalcémie, la détresse respiratoire, l'ictère et à la polyglobulie (et non à l'anémie).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Diabète et grossesse – complications néonatales p. 39-40\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant le cancer du col (cocher la réponse fausse) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'agent pathogène est le Human papilloma virus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il est de bon pronostic\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1er cancer de la femme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La multipartenariat sexuel est un facteur de risque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 1er cancer de la femme\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cancer du col est lié au papillomavirus (HPV 16 et 18) et au comportement sexuel (multipartenariat, rapports précoces). Ce n'est pas le 1er cancer de la femme : c'est le cancer du sein. Remarque : « Il est de bon pronostic » n'est vrai que pour les formes dépistées tôt ; seule l'option C est retenue comme fausse.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Cancer du col (facteurs de risque) ; Cancer du sein\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme V. consulte pour examen prénatal du 4e mois. Au spéculum on observe une muqueuse cervico-vaginale inflammatoire et des leucorrhées verdâtres, bulleuses et abondantes. L'aspect décrit permet d'évoquer a priori :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une mycose\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une endocervicite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une chlamydiose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une vaginose bactérienne\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une trichomonose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. Une trichomonose\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"Les leucorrhées à Trichomonas vaginalis sont très abondantes, liquides, mousseuses (bulleuses), verdâtres ou jaunâtres, avec un col rouge framboisé. La mycose donne des pertes blanches « lait caillé » ; la vaginose, des pertes grises à odeur de poisson.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Leucorrhées à Trichomonas vaginalis – signes cliniques\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Madame Rokia, âgée de 25 ans, est enceinte pour la 3e fois. Indiquez les 2 antécédents qui doivent faire dépister un diabète gestationnel.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le premier enfant pesait 4000 g.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"À sa deuxième grossesse, elle a eu une fausse couche spontanée à 10 SA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle est obèse, son IMC est supérieur à 25 kg/m2.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le deuxième enfant est drépanocytaire.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"À sa troisième grossesse, elle a eu une pyélonéphrite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le premier enfant pesait 4000 g. ; C. Elle est obèse, son IMC est supérieur à 25 kg/m2.\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les critères de O'Sullivan comprennent l'antécédent de gros enfant (macrosomie) et l'obésité. Une fausse couche isolée, un enfant drépanocytaire ou une pyélonéphrite ne sont pas des critères de dépistage. Remarque : Le cours fixe le gros fœtus à plus de 4000 g et l'obésité à un poids supérieur de 20 % au poids idéal ; les seuils de l'énoncé sont proches.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Diabète gestationnel – dépistage (critères de O'Sullivan) p. 45\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Citez 2 complications de la drépanocytose majeure au cours de la grossesse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les avortements.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'hypotrophie fœtale.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un hydramnios.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les hématomes rétro placentaires.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Aucune de ces réponses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les avortements. ; B. L'hypotrophie fœtale.\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Les complications fœtales de la drépanocytose majeure sont l'avortement spontané, l'accouchement prématuré, l'hypotrophie fœtale et la mort fœtale. L'hydramnios et l'HRP n'en font pas partie.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Hémoglobinopathies et grossesse – complications p. 17\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels éléments sont en faveur du diagnostic du placenta prævia ? Citez les 2 bonnes réponses\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémorragie abondante de sang rouge\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleurs utérines brutales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fréquente souffrance fœtale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Notion de curetage, de césarienne\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"HTA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Hémorragie abondante de sang rouge ; D. Notion de curetage, de césarienne\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Le placenta prævia saigne du sang rouge vif, de façon indolore et répétée, avec un fœtus qui va bien ; ses facteurs favorisants sont les cicatrices utérines (césarienne), les curetages/avortements et les manœuvres endo-utérines. Douleur brutale, souffrance fœtale et HTA orientent vers l'HRP.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Placenta prævia (étiologie, étude clinique)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Durant le cycle menstruel : Cocher la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La durée de la phase lutéale est constante\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'ovulation est précédée d'un pic de progestérone\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La phase ovulatoire dure toujours 14 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La durée de la phase lutéale est constante\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La phase lutéale (après l'ovulation) dure de façon assez fixe 12 à 14 jours : c'est la phase folliculaire qui varie et fait varier la longueur du cycle. L'ovulation est précédée d'un pic de LH, pas de progestérone.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Explorations (courbe thermique : phase lutéale 12-14 jours) p. 189\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hymen chez la femme vierge : Cocher la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Recouvre l'intégralité de l'orifice vaginal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Disparaît après les premières menstrues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Peut se présenter sous plusieurs formes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Peut se présenter sous plusieurs formes\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'hymen est un repli muqueux à l'entrée du vagin, de forme variable (annulaire, semi-lunaire, cribriforme…). Il laisse normalement passer les règles : s'il recouvre tout l'orifice (imperforation), le sang s'accumule (hématocolpos). Il ne disparaît pas avec les règles.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Aménorrhées – imperforation de l'hymen ; formes de l'hymen (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la mesure que l'on peut proposer pour prévenir la récidive de la pré-éclampsie chez une femme à haut risque ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le régime sans sel.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La prise de 100 mg d'aspirine par jour jusqu'à l'accouchement.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La prise d'un traitement hypertenseur depuis le début de la grossesse.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La prise de la tension artérielle à chaque CPN\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. La prise de la tension artérielle à chaque CPN\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La prise de la TA à chaque CPN permet de dépister précocement la récidive. L'option B est fausse par sa durée : l'aspirine doit être arrêtée vers 36 SA (ou 10 jours avant l'accouchement) à cause du risque hémorragique. Le régime sans sel est déconseillé. Remarque : L'aspirine reste la vraie mesure préventive du cours (voir question 32) ; ici, c'est la mention « jusqu'à l'accouchement » qui rend l'option B fausse.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), HTA et grossesse – aspirine (V-1.2)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez la femme enceinte atteinte de paludisme, on observe : Citez la réponse exacte\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Plus d'anémies que chez la femme non enceinte.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Moins d'anémies que chez la femme non enceinte.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Moins d'accès palustre que chez la femme non enceinte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Plus d'anémies que chez la femme non enceinte.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La grossesse diminue l'immunité : les accès palustres sont plus fréquents et plus graves, et l'anémie est plus fréquente que chez la femme non enceinte. D'où la triple prévention : MILDA, TPI par SP et assainissement.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 6-7 (en partie hors cours)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les complications maternelles de la drépanocytose majeure au cours de la grossesse sont : Citez les 2 bonnes réponses\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les infections urinaires.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La prise de poids excessive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les thromboses.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le placenta praevia.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La souffrance fœtale aigue\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les infections urinaires. ; C. Les thromboses.\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Les complications maternelles citées par le cours sont l'anémie, les infections (surtout urinaires et vaginales), la pré-éclampsie et les crises vaso-occlusives (obstruction des capillaires par les hématies falciformes). La souffrance fœtale aiguë est une complication fœtale. Remarque : Le cours parle de crises vaso-occlusives (micro-infarctus) plutôt que de « thromboses ».\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Hémoglobinopathies et grossesse – complications maternelles p. 17\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans quelle situation, il n'est pas recommandé, voire proscrit de pratiquer un TV ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hématome rétro-placentaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Suspicion de Placenta praevia\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Suspicion de rupture utérine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hématome décidual\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Suspicion de Placenta praevia\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant un placenta prævia, le TV intracervical est interdit car il peut déclencher une hémorragie abondante ; on évite les touchers fréquents et l'échographie confirme le diagnostic.\\n\\nSource : Gynéco L2 IDE (INFAS 2025), Placenta prævia – toucher vaginal ; SONU L2 SF (2025-2026), CAT devant un placenta prævia\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les gestes suivants, lequel ne doit pas être réalisé en cas de procidence du cordon battant :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Recouvrir le cordon avec des compresses humide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Installer la patiente en position de Trendelenburg\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faire des TV pour surveiller la descente du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire une césarienne en urgence\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Faire des TV pour surveiller la descente du fœtus\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Devant un cordon battant, on protège le cordon (compresses humides tièdes), on refoule la présentation et on met la patiente en Trendelenburg, puis on extrait l'enfant en urgence (césarienne si la dilatation n'est pas complète). Des TV répétés manipulent le cordon et retardent l'extraction.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__50\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique (réponse correcte = +1 ; réponse incorrecte = –1). Mme Touré M., sans profession, âgée de 27 ans, G4 P3, est hospitalisée à 37 semaines d'aménorrhée. À 21 h 30, elle est en début de travail, à 3 cm, poche des eaux bombante, sans métrorragies. La présentation est céphalique, fixée. La grossesse a été marquée par des métrorragies au 1er trimestre. L'échographie avait confirmé une insertion antérieure basse du placenta à 34 SA. Le taux d'hémoglobine avant l'accouchement a été trouvé à 10 g/100 ml. Le travail est dirigé (perfusion de Syntocinon®, rupture artificielle des membranes). L'accouchement a lieu après 15 h de travail, avec épisiotomie : naissance d'une fille pesant 4300 g. Le placenta et les annexes sont complets après la délivrance. L'examen de la filière génitale n'a pas révélé de lésions des parties molles. 30 min plus tard, la quantité de sang dans le bassin est mesurée à 300 ml. La patiente est obnubilée. La TA est à 75/60 (120/70 avant l'accouchement), le pouls à 122 (80 avant l'accouchement).\",\n       \"text\": \"Quel est votre diagnostic suite à ces résultats ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Suites de couches normales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémorragie du post partum immédiat\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Endométrite du post partum\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Hémorragie du post partum immédiat\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un saignement dans les 24 heures après l'accouchement, avec chute de la TA, tachycardie et obnubilation, est une hémorragie du post-partum immédiat. L'endométrite est une complication infectieuse plus tardive (fièvre, lochies fétides).\\n\\nSource : Module SONU – PNSME, Hémorragie du post-partum p. 50 ; SONU L2 SF (2025-2026), HPP – définitions\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__51\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique (réponse correcte = +1 ; réponse incorrecte = –1). Mme Touré M., sans profession, âgée de 27 ans, G4 P3, est hospitalisée à 37 semaines d'aménorrhée. À 21 h 30, elle est en début de travail, à 3 cm, poche des eaux bombante, sans métrorragies. La présentation est céphalique, fixée. La grossesse a été marquée par des métrorragies au 1er trimestre. L'échographie avait confirmé une insertion antérieure basse du placenta à 34 SA. Le taux d'hémoglobine avant l'accouchement a été trouvé à 10 g/100 ml. Le travail est dirigé (perfusion de Syntocinon®, rupture artificielle des membranes). L'accouchement a lieu après 15 h de travail, avec épisiotomie : naissance d'une fille pesant 4300 g. Le placenta et les annexes sont complets après la délivrance. L'examen de la filière génitale n'a pas révélé de lésions des parties molles. 30 min plus tard, la quantité de sang dans le bassin est mesurée à 300 ml. La patiente est obnubilée. La TA est à 75/60 (120/70 avant l'accouchement), le pouls à 122 (80 avant l'accouchement).\",\n       \"text\": \"Dans cette situation, on peut dire qu'il s'agit d'une hémorragie du post partum immédiat parce que :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle est inférieure à 500 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le pouls s'accélère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Il n'y a pas de lésion traumatique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La tension artérielle s'abaisse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Le pouls s'accélère ; D. La tension artérielle s'abaisse\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"L'HPP se définit par une perte de plus de 500 ml après un accouchement par voie basse ou par une perte qui entraîne une instabilité hémodynamique (chute de la TA, tachycardie). Ici, 300 ml seulement mais TA 75/60 et pouls 122 : c'est une HPP.\\n\\nSource : SONU L2 SF (2025-2026), Hémorragie du post-partum – définition\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__52\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique (réponse correcte = +1 ; réponse incorrecte = –1). Mme Touré M., sans profession, âgée de 27 ans, G4 P3, est hospitalisée à 37 semaines d'aménorrhée. À 21 h 30, elle est en début de travail, à 3 cm, poche des eaux bombante, sans métrorragies. La présentation est céphalique, fixée. La grossesse a été marquée par des métrorragies au 1er trimestre. L'échographie avait confirmé une insertion antérieure basse du placenta à 34 SA. Le taux d'hémoglobine avant l'accouchement a été trouvé à 10 g/100 ml. Le travail est dirigé (perfusion de Syntocinon®, rupture artificielle des membranes). L'accouchement a lieu après 15 h de travail, avec épisiotomie : naissance d'une fille pesant 4300 g. Le placenta et les annexes sont complets après la délivrance. L'examen de la filière génitale n'a pas révélé de lésions des parties molles. 30 min plus tard, la quantité de sang dans le bassin est mesurée à 300 ml. La patiente est obnubilée. La TA est à 75/60 (120/70 avant l'accouchement), le pouls à 122 (80 avant l'accouchement).\",\n       \"text\": \"La cause de cette hémorragie du post partum immédiat peut être ici :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une hypotonie utérine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une déchirure du col\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une déchirure vaginale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'anémie antérieure\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une hypotonie utérine\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le placenta est complet et la filière génitale est sans lésion : il reste l'atonie (hypotonie) utérine, favorisée ici par le travail long (15 h) dirigé au Syntocinon®, le gros enfant (4300 g) et la multiparité. L'anémie aggrave la tolérance mais n'est pas la cause du saignement.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), HPPI par atonie utérine p. 57-59 ; Module SONU – PNSME, les 4T p. 50\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__53\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique (réponse correcte = +1 ; réponse incorrecte = –1). Mme Touré M., sans profession, âgée de 27 ans, G4 P3, est hospitalisée à 37 semaines d'aménorrhée. À 21 h 30, elle est en début de travail, à 3 cm, poche des eaux bombante, sans métrorragies. La présentation est céphalique, fixée. La grossesse a été marquée par des métrorragies au 1er trimestre. L'échographie avait confirmé une insertion antérieure basse du placenta à 34 SA. Le taux d'hémoglobine avant l'accouchement a été trouvé à 10 g/100 ml. Le travail est dirigé (perfusion de Syntocinon®, rupture artificielle des membranes). L'accouchement a lieu après 15 h de travail, avec épisiotomie : naissance d'une fille pesant 4300 g. Le placenta et les annexes sont complets après la délivrance. L'examen de la filière génitale n'a pas révélé de lésions des parties molles. 30 min plus tard, la quantité de sang dans le bassin est mesurée à 300 ml. La patiente est obnubilée. La TA est à 75/60 (120/70 avant l'accouchement), le pouls à 122 (80 avant l'accouchement).\",\n       \"text\": \"Dans cette situation, il faut :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réaliser une révision utérine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mettre en place une perfusion d'ocytociques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Vérifier l'intégrité du col utérin (si déchirure, la suturer)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Vérifier l'intégrité du vagin (si déchirure, la suturer)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Mettre en place une perfusion d'ocytociques\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant une atonie, on prend une bonne voie veineuse avec 10 UI d'ocytocine dans 500 ml de sérum salé et on masse l'utérus. Le col et le vagin ont déjà été examinés (pas de lésion), C et D ne sont donc plus à faire.\\n\\nSource : Cours de soins obstétricaux L2 SF, CAT devant une atonie utérine p. 107 ; Gynécologie-Obstétrique L3 SF (INFAS 2024-2025) p. 59\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__54\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique (réponse correcte = +1 ; réponse incorrecte = –1). Mme Touré M., sans profession, âgée de 27 ans, G4 P3, est hospitalisée à 37 semaines d'aménorrhée. À 21 h 30, elle est en début de travail, à 3 cm, poche des eaux bombante, sans métrorragies. La présentation est céphalique, fixée. La grossesse a été marquée par des métrorragies au 1er trimestre. L'échographie avait confirmé une insertion antérieure basse du placenta à 34 SA. Le taux d'hémoglobine avant l'accouchement a été trouvé à 10 g/100 ml. Le travail est dirigé (perfusion de Syntocinon®, rupture artificielle des membranes). L'accouchement a lieu après 15 h de travail, avec épisiotomie : naissance d'une fille pesant 4300 g. Le placenta et les annexes sont complets après la délivrance. L'examen de la filière génitale n'a pas révélé de lésions des parties molles. 30 min plus tard, la quantité de sang dans le bassin est mesurée à 300 ml. La patiente est obnubilée. La TA est à 75/60 (120/70 avant l'accouchement), le pouls à 122 (80 avant l'accouchement).\",\n       \"text\": \"Si malgré ces mesures, le saignement anormal persiste parce que l'utérus reste hypotonique, vous pouvez avoir recours à ces gestes suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réaliser un massage de l'utérus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Réaliser une injection intramusculaire de Syntocinon® ou de prostaglandines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser une ligature des artères hypogastriques\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ralentir la perfusion IV ou de prostaglandines\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Mettre en place un ballonnet intra-utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Réaliser un massage de l'utérus ; E. Mettre en place un ballonnet intra-utérin\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Si l'atonie persiste : massage utérin, compression bimanuelle, misoprostol par voie rectale, puis tamponnement intra-utérin par ballonnet (préservatif sur sonde de Foley). La ligature des artères hypogastriques est un geste chirurgical en centre de référence ; ralentir la perfusion est contraire au but. Remarque : Le cours prévoit l'ocytocine en perfusion et le misoprostol par voie rectale plutôt qu'une injection IM ; c'est pourquoi l'option B n'est pas retenue.\\n\\nSource : Cours de soins obstétricaux L2 SF, CAT devant une atonie utérine p. 107 ; Module SONU – PNSME, pose du ballonnet intra-utérin p. 62\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j4-sf3__55\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique (réponse correcte = +1 ; réponse incorrecte = –1). Mme Touré M., sans profession, âgée de 27 ans, G4 P3, est hospitalisée à 37 semaines d'aménorrhée. À 21 h 30, elle est en début de travail, à 3 cm, poche des eaux bombante, sans métrorragies. La présentation est céphalique, fixée. La grossesse a été marquée par des métrorragies au 1er trimestre. L'échographie avait confirmé une insertion antérieure basse du placenta à 34 SA. Le taux d'hémoglobine avant l'accouchement a été trouvé à 10 g/100 ml. Le travail est dirigé (perfusion de Syntocinon®, rupture artificielle des membranes). L'accouchement a lieu après 15 h de travail, avec épisiotomie : naissance d'une fille pesant 4300 g. Le placenta et les annexes sont complets après la délivrance. L'examen de la filière génitale n'a pas révélé de lésions des parties molles. 30 min plus tard, la quantité de sang dans le bassin est mesurée à 300 ml. La patiente est obnubilée. La TA est à 75/60 (120/70 avant l'accouchement), le pouls à 122 (80 avant l'accouchement).\",\n       \"text\": \"Les mesures misent en place réussissent à arrêter les saignements. La patiente souhaite être mise sous contraception avant sa sortie. Quels sont les 2 méthodes que vous lui proposez ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La contraception orale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le dispositif intra-utérin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'implant\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les contraceptifs injectables\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La ligature tubaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Le dispositif intra-utérin ; C. L'implant\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Dans le post-partum immédiat, le DIU peut être posé dans les 48 premières heures (catégorie 1) et l'implant est utilisable (catégorie 2). Les injectables (catégorie 3 avant 48 h chez la femme qui allaite) et les œstroprogestatifs (catégorie 4) sont à éviter. Remarque : La ligature tubaire est aussi possible après l'accouchement, mais c'est une méthode définitive ; la correction nationale de la Prépa DE (les J) retient les deux méthodes de longue durée réversibles.\\n\\nSource : Cours de SR/PF L2 (INFAS 2023), DIU du post-partum et critères d'éligibilité (3.5) ; Document SSR L2 SF (cours SR/PF, INFAS)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
